{"content": "const API_BASE = 'http://localhost:3001/api';

function createApp() {
    const messageList = document.getElementById('message-list');
    const messageForm = document.getElementById('message-form');
    const messageInput = document.getElementById('message-input');

    function appendMessage(message) {
        const div = document.createElement('div');
        div.className = 'message';

        const timestamp = document.createElement('div');
        timestamp.className = 'timestamp';
        timestamp.textContent = new Date(message.created_at).toLocaleString();

        const text = document.createElement('div');
        text.textContent = message.text;

        div.appendChild(timestamp);
        div.appendChild(text);
        messageList.appendChild(div);

        // Scroll to bottom
        messageList.scrollTop = messageList.scrollHeight;
    }

    // Initial fetch
    async function fetchMessages() {
        try {
            const response = await fetch(`${API_BASE}/messages`);
            const messages = await response.json();
            messageList.innerHTML = '';
            messages.forEach(appendMessage);
        } catch (err) {
            console.error('Error fetching messages:', err);
        }
    }

    // SSE Connection
    function setupSSE() {
        const eventSource = new EventSource(`${API_BASE}/stream`);

        eventSource.onmessage = (event) => {
            const newMessage = JSON.parse(event.data);
            appendMessage(newMessage);
        };

        eventSource.onerror = (err) => {
            console.error('SSE Error:', err);
            // EventSource will automatically try to reconnect, 
            // but we could handle it here if needed.
        };
    }

    // Form handling
    messageForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const text = messageInput.value.trim();
        if (!text) return;

        messageInput.value = '';

        try {
            const response = await fetch(`${API_BASE}/messages`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ text })
            });

            if (!response.ok) {
                throw new Error('Failed to post message');
            }
        } catch (err) {
            console.error('Error posting message:', err);
            alert('Failed to send message');
        }
    });

    fetchMessages();
    setupSSE();
}

// Export for use in index.html if needed, although we're using type="module"
if (typeof module !== 'undefined') {
    module.exports = { createApp };
} else {
    // In the browser
    window.createApp = createApp;
}
